$j = Get-Content -Raw "C:\Users\ygyg4\OneDrive\Documents\Craft Anything\roamingcamelsmorocco-com\capture\capture.json" -Encoding utf8 | ConvertFrom-Json
$rows = $j.outline | ForEach-Object {
  $t = if ($_.text) { ($_.text -replace "\r?\n"," / ") } else { "" }
  if ($t.Length -gt 70) { $t = $t.Substring(0,70) + "..." }
  $b = if ($_.box) { "$($_.box.x),$($_.box.y) $($_.box.w)x$($_.box.h)" } else { "" }
  $role = $_.role
  $href = if ($_.href) { ($_.href -replace 'https://roamingcamelsmorocco\.com','') } else { "" }
  if ($href.Length -gt 60) { $href = $href.Substring(0,60) }
  "{0,-12} {1,-30} {2,-16} {3,-9} {4,-60} {5}" -f $_.tag, $role, $b, ($_.font -replace ' 400',''), $t, $href
}
$rows -join "`n" | Out-File "C:\Users\ygyg4\AppData\Local\Temp\rcm-outline.txt" -Encoding utf8
Get-Content "C:\Users\ygyg4\AppData\Local\Temp\rcm-outline.txt" -TotalCount 120

$h = Get-Content -Raw "C:\Users\ygyg4\OneDrive\Documents\Craft Anything\roamingcamelsmorocco-com\capture\page.html" -Encoding utf8
foreach ($needle in @("Extended Tours","Day Trips","Let's personalize","We Understand Luxury Travel","Join Our Newsletter")) {
  $i = $h.IndexOf($needle)
